-- =====================================================================
--  SAMMS — Extended dataset
--
--  Replaces the sample seed data with a larger dataset spanning
--  January 2023 to May 2026, suitable for trend analysis and
--  business intelligence reporting.
--
--  Prerequisite: import samms_db.sql first (schema).
--  All records are fictitious.
-- =====================================================================

SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;
USE samms;

-- TRUNCATE is refused on tables referenced by a foreign key even with
-- FOREIGN_KEY_CHECKS disabled, so rows are removed with DELETE and the
-- auto-increment counters are reset explicitly.
SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM RequestStatusLog;
DELETE FROM Maintenance;
DELETE FROM MaintenanceRequests;
DELETE FROM Assets;
DELETE FROM Users;

ALTER TABLE RequestStatusLog    AUTO_INCREMENT = 1;
ALTER TABLE Maintenance         AUTO_INCREMENT = 1;
ALTER TABLE MaintenanceRequests AUTO_INCREMENT = 1;
ALTER TABLE Assets              AUTO_INCREMENT = 1;
ALTER TABLE Users               AUTO_INCREMENT = 1;

SET FOREIGN_KEY_CHECKS = 1;


